require_once __DIR__.'/includes/auth.php';require_role('student');require_once __DIR__.'/includes/clearance_functions.php';$student=get_student_by_user($pdo,current_user());$request=get_latest_clearance_request($pdo,$student['student_id']);$missing=clearance_eligibility($pdo,$student);$message='';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if($request&&$request['overall_status']==='Rejected'){$message=resubmit_clearance_request($pdo,$request,$_SESSION['user_id']);if(strpos($message,'resubmitted')===false)$error=$message;}elseif($request&&$request['overall_status']==='Final'){$error='Clearance has already been completed. A new clearance request cannot be initiated for this student.';}elseif(!$request){$r=initiate_clearance($pdo,$student,$_SESSION['user_id']);if(isset($r['request_id']))$message='Clearance initiated and sent to the Institute Director.';else$error=$r['error'];}else$error='You already have an active clearance request.';$request=get_latest_clearance_request($pdo,$student['student_id']);$missing=clearance_eligibility($pdo,$student);}$page_title='Initiate Clearance';require_once __DIR__.'/includes/header.php';?><section class="dashboard"><div class="dashboard-top"><h1>Clearance Request</h1><a href="dashboard.php">Back to dashboard</a></div><div class="dashboard-box"><?php if($message):?><div class="success"><?=htmlspecialchars($message)?></div><?php endif;?><?php if($error):?><div class="alert"><?=htmlspecialchars($error)?></div><?php endif;?><?php if($request):?><p><strong>Current status:</strong> <?=htmlspecialchars($request['overall_status'])?><?php if($request['current_department']):?> — <?=htmlspecialchars($request['current_department'])?><?php endif;?></p><?php endif;?><?php if($request&&$request['overall_status']==='Rejected'):?><p class="alert">Correct the issue described in Tracking, then resubmit. Your request will return to the rejecting department.</p><form method="post"><?php echo csrf_field(); ?><button>Resubmit clearance</button></form><?php elseif($request&&$request['overall_status']==='Final'):?><p class="success">Your clearance has been completed. All workflow departments have approved this clearance.</p><span class="button disabled" aria-disabled="true">Initiate Clearance</span><?php elseif(!$request):?><?php if($missing):?><p class="alert">Not eligible yet. Complete: <?=htmlspecialchars(implode(', ',$missing))?>.</p><a class="button secondary" href="student_profile.php">Complete profile</a><?php else:?><p class="success">Eligible to initiate clearance.</p><form method="post"><?php echo csrf_field(); ?><button>Initiate Clearance</button></form><?php endif;?><?php endif;?></div></section><?php require_once __DIR__.'/includes/footer.php';?>


